#!/usr/bin/env python3
# _dll_bundle.py —— 闭源解码 DLL 的 base64 内嵌包（运行时提取，规避平台拒绝 .dll）
# 由 caj2pdf-restructured 的 4 个 DLL 生成；extract_dlls(root) 把它们写到
# root/caj2pdf/dep/bin、root/caj2pdf/bin、root/dlls（与原始布局一致，保证 caj2pdf 正常加载）。
import os
import base64

_NAMES = [
    'libjbigdec-w32.dll',
    'libjbigdec-w64.dll',
    'libjbig2codec-w32.dll',
    'libjbig2codec-w64.dll',
]

_B64 = {
    'libjbigdec-w32.dll': '',
    'libjbigdec-w64.dll': '',
    'libjbig2codec-w32.dll': '',
    'libjbig2codec-w64.dll': '',
}


def extract_dlls(root):
    """把 4 个 DLL 提取到 root 下三处 bin 目录（与原始布局一致）。已存在则跳过。"""
    targets = [
        os.path.join(root, "caj2pdf", "dep", "bin"),
        os.path.join(root, "caj2pdf", "bin"),
        os.path.join(root, "dlls"),
    ]
    for t in targets:
        os.makedirs(t, exist_ok=True)
        for name in _NAMES:
            p = os.path.join(t, name)
            if not os.path.exists(p):
                with open(p, "wb") as f:
                    f.write(base64.b64decode(_B64[name]))


if __name__ == "__main__":
    extract_dlls(os.path.dirname(os.path.abspath(__file__)))
